-- EduSasa canonical 006: attendance.
CREATE TABLE IF NOT EXISTS attendance (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, school_id BIGINT UNSIGNED NOT NULL, student_id BIGINT UNSIGNED NOT NULL, class_id BIGINT UNSIGNED NOT NULL, stream_id BIGINT UNSIGNED NULL, academic_year_id BIGINT UNSIGNED NULL, term_id BIGINT UNSIGNED NULL, attendance_date DATE NOT NULL, status ENUM('present','absent','late','excused') NOT NULL, remarks VARCHAR(500) NULL, recorded_by BIGINT UNSIGNED NULL, deleted_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_attendance_student_date(school_id,student_id,attendance_date), KEY idx_attendance_class_date(school_id,class_id,attendance_date), KEY idx_attendance_stream_date(school_id,stream_id,attendance_date), KEY idx_attendance_student_date(student_id,attendance_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
